css:
[data-bz-section="pg-faq"] .bz-headingblock h2 { margin-bottom: 40px; }
/* Accordion: one <details> per question; the question is the clickable row, the answer opens beneath it. */
[data-bz-section="pg-faq"] .bz-faqs { gap: 0; border-top: 1px solid var(--line); }
[data-bz-section="pg-faq"] .bz-faq { background: none; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; padding: 0; }
[data-bz-section="pg-faq"] .bz-faq summary { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 22px 0; cursor: pointer; list-style: none; font: 700 18px / 1.4 var(--font-heading); color: var(--ink); transition: color 0.15s ease; }
[data-bz-section="pg-faq"] .bz-faq summary::-webkit-details-marker { display: none; }
[data-bz-section="pg-faq"] .bz-faq summary:hover { color: var(--accent); }
[data-bz-section="pg-faq"] .bz-faq summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; border-radius: 2px; }
/* Plus that turns into a minus when the answer is open. */
[data-bz-section="pg-faq"] .bz-faq summary::after { content: ""; flex: 0 0 22px; width: 22px; height: 22px; background: linear-gradient(currentColor, currentColor) center / 14px 2px no-repeat, linear-gradient(currentColor, currentColor) center / 2px 14px no-repeat; border: 1.5px solid currentColor; border-radius: 50%; opacity: 0.8; transition: transform 0.2s ease; }
[data-bz-section="pg-faq"] .bz-faq[open] summary::after { background: linear-gradient(currentColor, currentColor) center / 12px 2px no-repeat; transform: rotate(180deg); }
[data-bz-section="pg-faq"] .bz-faq[open] summary { color: var(--accent); }
[data-bz-section="pg-faq"] .bz-faq__a { margin: 0; padding: 0 46px 24px 0; font-size: 16px; line-height: 1.65; color: var(--copy); }
@media (max-width: 640px) { [data-bz-section="pg-faq"] .bz-faq summary { font-size: 16px; padding: 18px 0; } [data-bz-section="pg-faq"] .bz-faq__a { padding-right: 0; font-size: 15px; } }
@media (prefers-reduced-motion: reduce) { [data-bz-section="pg-faq"] .bz-faq summary, [data-bz-section="pg-faq"] .bz-faq summary::after { transition: none; } }

js:
// FAQ accordion: native <details> (works without script, keyboard and screen-reader friendly). This only makes it open one answer at a time.
document.querySelectorAll('[data-bz-section="pg-faq"] .bz-faqs').forEach(function (list) {
  var items = list.querySelectorAll('details.bz-faq');
  items.forEach(function (item) {
    item.addEventListener('toggle', function () {
      if (!item.open) return;
      items.forEach(function (other) { if (other !== item) other.open = false; });
    });
  });
});
